#!/bin/sh
# TSP_PORTABLE_ZRAM_BACKEND_V1
# One root-level memory backend for the TrimUI Smart Pro OpenMW port.
# Source this AFTER the launcher's built-in swap/zram function definitions and
# BEFORE its tsp_memory_setup call.
#
# Public API:
#   tsp_portable_zram_start
#   tsp_portable_zram_stop
#   tsp_memory_setup      (launcher override)
#   tsp_zram_release      (launcher cleanup override)
#
# Policy:
#   muOS   - never use file/loop swap. Temporarily replace ONLY the exact known
#            4.9.191 stock zsmalloc module with the bundled no-page-migration
#            build, then let muOS's own swap.sh create its normal 512 MiB LZO
#            zram device. Restore the user's original muOS settings on exit.
#   Knulli - never use file/loop swap. Use Knulli's native zramswap service.
#            If Knulli happens to ship the exact same stock zsmalloc module hash
#            as the muOS build, use the same bundled no-migration module too.
#            Otherwise leave Knulli's allocator untouched; no cross-kernel module
#            is forced. A later Knulli-specific payload can be added here without
#            changing the main launcher.
#   other  - call the launcher's original tsp_setup_swap path unchanged.
#
# The module payload is embedded in THIS file, so the game package only needs
# one extra root-level file: $GAMEDIR/tsp_zram_portable.sh

TSP_PZ_VERSION="tsp-portable-zram-2026-09-18-v1"
TSP_PZ_SIZE_MB="${TSP_ZRAM_MB:-512}"
TSP_PZ_ACTIVE=0
TSP_PZ_MODE=""
TSP_PZ_OS=""
TSP_PZ_PATCH_ACTIVE=0
TSP_PZ_KNULLI_WAS_ACTIVE=0
TSP_PZ_TMP="${TMPDIR:-/tmp}/tsp-portable-zram.$$"
TSP_PZ_STATE="${GAMEDIR:-/tmp}/.tsp-portable-zram-state"
TSP_PZ_LEGACY_MUOS_STATE="${GAMEDIR:-/tmp}/.tsp-muos-zram-owned"

TSP_PZ_PATCH_SHA="a3d337f9e537d57344bbeb849db9757a32b8f623c63e98ade99381d00d1dcd4a"
TSP_PZ_KNOWN_STOCK_ZSM_SHA="61bf3abc8a41505113dea2d4443045d180244250e3f6b083518b013bd7b30e87"
TSP_PZ_PATCH_FILE="$TSP_PZ_TMP/zsmalloc-no-page-migrate.ko"

TSP_PZ_MUOS_ZRAM_CFG="/opt/muos/config/settings/advanced/zramfile"
TSP_PZ_MUOS_SWAP_CFG="/opt/muos/config/settings/advanced/swapfile"
TSP_PZ_MUOS_SWAP_SCRIPT="/opt/muos/script/system/swap.sh"

TSP_PZ_MUOS_OLD_ZRAM=""
TSP_PZ_MUOS_OLD_SWAP=""
TSP_PZ_KNULLI_SERVICE=""

# ----------------------------- common helpers -----------------------------

tsp_pz_detect_os() {
    TSP_PZ_OS=""
    if [ -d /opt/muos ]; then
        TSP_PZ_OS="muOS"
        return 0
    fi

    _pz_cfw=$(printf '%s' "${CFW_NAME:-}" | tr '[:upper:]' '[:lower:]')
    case "$_pz_cfw" in
        *knulli*) TSP_PZ_OS="Knulli"; return 0 ;;
    esac

    if grep -qi 'knulli' /etc/os-release /usr/share/batocera/batocera.version 2>/dev/null; then
        TSP_PZ_OS="Knulli"
        return 0
    fi
    return 1
}

tsp_pz_zram_dev() {
    awk 'NR>1 && $1 ~ /^\/dev\/zram[0-9]+$/ {print $1; exit}' /proc/swaps 2>/dev/null
}

tsp_pz_is_uint() {
    case "$1" in ''|*[!0-9]*) return 1 ;; esac
    return 0
}

tsp_pz_sha256() {
    sha256sum "$1" 2>/dev/null | awk '{print $1}'
}

tsp_pz_module_path() {
    _pz_name=$1
    _pz_p=$(modinfo -n "$_pz_name" 2>/dev/null || true)
    [ -n "$_pz_p" ] && [ -f "$_pz_p" ] && { printf '%s\n' "$_pz_p"; return 0; }
    return 1
}

tsp_pz_decode_patch() {
    mkdir -p "$TSP_PZ_TMP" || return 1
    rm -f "$TSP_PZ_PATCH_FILE" "$TSP_PZ_PATCH_FILE.b64" 2>/dev/null || true
    tsp_pz_emit_patch_b64 > "$TSP_PZ_PATCH_FILE.b64" || return 1

    if command -v base64 >/dev/null 2>&1; then
        base64 -d "$TSP_PZ_PATCH_FILE.b64" > "$TSP_PZ_PATCH_FILE" 2>/dev/null || return 1
    elif command -v busybox >/dev/null 2>&1; then
        busybox base64 -d "$TSP_PZ_PATCH_FILE.b64" > "$TSP_PZ_PATCH_FILE" 2>/dev/null || return 1
    else
        echo "PORTABLE ZRAM: no base64 decoder available"
        return 1
    fi

    rm -f "$TSP_PZ_PATCH_FILE.b64" 2>/dev/null || true
    _pz_sha=$(tsp_pz_sha256 "$TSP_PZ_PATCH_FILE")
    if [ "$_pz_sha" != "$TSP_PZ_PATCH_SHA" ]; then
        echo "PORTABLE ZRAM: embedded module hash mismatch"
        echo "PORTABLE ZRAM: actual=$_pz_sha"
        echo "PORTABLE ZRAM: expected=$TSP_PZ_PATCH_SHA"
        rm -f "$TSP_PZ_PATCH_FILE"
        return 1
    fi
    chmod 0600 "$TSP_PZ_PATCH_FILE" 2>/dev/null || true
    return 0
}

tsp_pz_unload_module_stack() {
    # Caller must have already removed zram from /proc/swaps.
    if grep -q '^zram ' /proc/modules 2>/dev/null; then
        modprobe -r zram >/dev/null 2>&1 || true
    fi
    if grep -q '^zsmalloc ' /proc/modules 2>/dev/null; then
        modprobe -r zsmalloc >/dev/null 2>&1 || true
    fi

    if grep -Eq '^(zram|zsmalloc) ' /proc/modules 2>/dev/null; then
        return 1
    fi
    return 0
}

tsp_pz_load_patch() {
    [ "$(uname -m 2>/dev/null)" = "aarch64" ] || {
        echo "PORTABLE ZRAM: patched allocator is ARM64-only"
        return 1
    }
    [ "$(uname -r 2>/dev/null)" = "4.9.191" ] || {
        echo "PORTABLE ZRAM: patched allocator requires kernel 4.9.191"
        return 1
    }

    tsp_pz_decode_patch || return 1
    insmod "$TSP_PZ_PATCH_FILE" || return 1
    if ! grep -q '^zsmalloc ' /proc/modules 2>/dev/null; then
        echo "PORTABLE ZRAM: insmod returned but zsmalloc is not loaded"
        return 1
    fi

    TSP_PZ_PATCH_ACTIVE=1
    echo "PORTABLE ZRAM: patched zsmalloc loaded (page migration disabled)"
    return 0
}

tsp_pz_unload_patch() {
    if [ "$TSP_PZ_PATCH_ACTIVE" = 1 ] || grep -q '^zsmalloc ' /proc/modules 2>/dev/null; then
        modprobe -r zram >/dev/null 2>&1 || true
        modprobe -r zsmalloc >/dev/null 2>&1 || true
    fi
    TSP_PZ_PATCH_ACTIVE=0
    rm -rf "$TSP_PZ_TMP" 2>/dev/null || true
}

tsp_pz_state_get() {
    _pz_key=$1
    [ -r "$TSP_PZ_STATE" ] || return 1
    awk -F= -v k="$_pz_key" '$1==k {sub(/^[^=]*=/, ""); print; exit}' "$TSP_PZ_STATE"
}

tsp_pz_state_clear() {
    rm -f "$TSP_PZ_STATE" 2>/dev/null || true
}

# ------------------------------- muOS path -------------------------------

tsp_pz_muos_apply() {
    [ -x "$TSP_PZ_MUOS_SWAP_SCRIPT" ] || return 1
    "$TSP_PZ_MUOS_SWAP_SCRIPT"
}

tsp_pz_muos_recover_legacy() {
    [ -r "$TSP_PZ_LEGACY_MUOS_STATE" ] || return 0
    [ -r "$TSP_PZ_MUOS_ZRAM_CFG" ] && [ -w "$TSP_PZ_MUOS_ZRAM_CFG" ] || return 1

    _pz_orig=$(awk -F= '$1=="original" {print $2; exit}' "$TSP_PZ_LEGACY_MUOS_STATE")
    _pz_temp=$(awk -F= '$1=="temporary" {print $2; exit}' "$TSP_PZ_LEGACY_MUOS_STATE")
    _pz_now=$(cat "$TSP_PZ_MUOS_ZRAM_CFG" 2>/dev/null)

    tsp_pz_is_uint "$_pz_orig" || return 1
    tsp_pz_is_uint "$_pz_temp" || return 1

    if [ "$_pz_now" = "$_pz_temp" ]; then
        echo "PORTABLE ZRAM: recovering legacy launcher-owned muOS ZRAM setting $_pz_temp -> $_pz_orig"
        printf '%s\n' "$_pz_orig" > "$TSP_PZ_MUOS_ZRAM_CFG" || return 1
        tsp_pz_muos_apply || return 1
    fi
    rm -f "$TSP_PZ_LEGACY_MUOS_STATE" 2>/dev/null || true
    return 0
}

tsp_pz_muos_recover_ours() {
    [ -r "$TSP_PZ_STATE" ] || return 0
    [ "$(tsp_pz_state_get os 2>/dev/null)" = "muOS" ] || return 0

    _pz_oldz=$(tsp_pz_state_get muos_old_zram 2>/dev/null || true)
    _pz_olds=$(tsp_pz_state_get muos_old_swap 2>/dev/null || true)
    _pz_temp=$(tsp_pz_state_get temp_mb 2>/dev/null || true)
    tsp_pz_is_uint "$_pz_oldz" || { echo "PORTABLE ZRAM: stale muOS state invalid; preserving settings"; return 1; }
    tsp_pz_is_uint "$_pz_olds" || return 1
    tsp_pz_is_uint "$_pz_temp" || return 1

    _pz_nowz=$(cat "$TSP_PZ_MUOS_ZRAM_CFG" 2>/dev/null || true)
    _pz_nows=$(cat "$TSP_PZ_MUOS_SWAP_CFG" 2>/dev/null || true)

    if [ "$_pz_nowz" = "$_pz_temp" ] && [ "$_pz_nows" = 0 ]; then
        echo "PORTABLE ZRAM: recovering state left by interrupted prior run"
        printf '%s\n' "$_pz_oldz" > "$TSP_PZ_MUOS_ZRAM_CFG" || return 1
        printf '%s\n' "$_pz_olds" > "$TSP_PZ_MUOS_SWAP_CFG" || return 1
        tsp_pz_muos_apply || return 1
        tsp_pz_state_clear
        return 0
    fi

    echo "PORTABLE ZRAM: stale state exists but muOS settings were changed externally; preserving them"
    tsp_pz_state_clear
    return 0
}

tsp_pz_muos_restore() {
    [ -r "$TSP_PZ_STATE" ] || return 0
    _pz_oldz=$(tsp_pz_state_get muos_old_zram 2>/dev/null || true)
    _pz_olds=$(tsp_pz_state_get muos_old_swap 2>/dev/null || true)
    tsp_pz_is_uint "$_pz_oldz" || return 1
    tsp_pz_is_uint "$_pz_olds" || return 1

    # First remove launcher-owned zram/swap while patched zsmalloc is still loaded.
    printf '0\n' > "$TSP_PZ_MUOS_ZRAM_CFG" 2>/dev/null || true
    printf '0\n' > "$TSP_PZ_MUOS_SWAP_CFG" 2>/dev/null || true
    tsp_pz_muos_apply >/dev/null 2>&1 || true

    if grep -q '^/dev/zram[0-9][0-9]* ' /proc/swaps 2>/dev/null; then
        echo "PORTABLE ZRAM: WARNING muOS native purge left zram active; not forcing module removal"
        return 1
    fi

    tsp_pz_unload_patch

    # Put the user's original OS settings back using the OS's own implementation.
    printf '%s\n' "$_pz_oldz" > "$TSP_PZ_MUOS_ZRAM_CFG" || return 1
    printf '%s\n' "$_pz_olds" > "$TSP_PZ_MUOS_SWAP_CFG" || return 1
    tsp_pz_muos_apply >/dev/null 2>&1 || {
        echo "PORTABLE ZRAM: WARNING failed to re-apply original muOS swap settings"
        return 1
    }

    tsp_pz_state_clear
    echo "PORTABLE ZRAM: muOS original zram=$_pz_oldz swapfile=$_pz_olds restored"
    return 0
}

tsp_pz_muos_start() {
    [ -r "$TSP_PZ_MUOS_ZRAM_CFG" ] && [ -w "$TSP_PZ_MUOS_ZRAM_CFG" ] || {
        echo "PORTABLE ZRAM: muOS zram setting unavailable"
        return 1
    }
    [ -r "$TSP_PZ_MUOS_SWAP_CFG" ] && [ -w "$TSP_PZ_MUOS_SWAP_CFG" ] || {
        echo "PORTABLE ZRAM: muOS swapfile setting unavailable"
        return 1
    }
    [ -x "$TSP_PZ_MUOS_SWAP_SCRIPT" ] || {
        echo "PORTABLE ZRAM: muOS native swap.sh unavailable"
        return 1
    }

    tsp_pz_muos_recover_legacy || true
    tsp_pz_muos_recover_ours || true

    TSP_PZ_MUOS_OLD_ZRAM=$(cat "$TSP_PZ_MUOS_ZRAM_CFG" 2>/dev/null || true)
    TSP_PZ_MUOS_OLD_SWAP=$(cat "$TSP_PZ_MUOS_SWAP_CFG" 2>/dev/null || true)
    tsp_pz_is_uint "$TSP_PZ_MUOS_OLD_ZRAM" || return 1
    tsp_pz_is_uint "$TSP_PZ_MUOS_OLD_SWAP" || return 1
    tsp_pz_is_uint "$TSP_PZ_SIZE_MB" || TSP_PZ_SIZE_MB=512

    {
        echo "version=$TSP_PZ_VERSION"
        echo "os=muOS"
        echo "temp_mb=$TSP_PZ_SIZE_MB"
        echo "muos_old_zram=$TSP_PZ_MUOS_OLD_ZRAM"
        echo "muos_old_swap=$TSP_PZ_MUOS_OLD_SWAP"
    } > "$TSP_PZ_STATE" || return 1
    sync

    # Purge every OS-managed swap device before replacing the allocator module.
    printf '0\n' > "$TSP_PZ_MUOS_ZRAM_CFG" || return 1
    printf '0\n' > "$TSP_PZ_MUOS_SWAP_CFG" || return 1
    tsp_pz_muos_apply >/dev/null 2>&1 || {
        echo "PORTABLE ZRAM: muOS native purge failed"
        tsp_pz_muos_restore || true
        return 1
    }

    if grep -q '^/dev/zram[0-9][0-9]* ' /proc/swaps 2>/dev/null; then
        echo "PORTABLE ZRAM: zram still active after native muOS purge"
        tsp_pz_muos_restore || true
        return 1
    fi

    if ! tsp_pz_unload_module_stack; then
        echo "PORTABLE ZRAM: stock zram/zsmalloc modules are still busy"
        grep -E '^(zram|zsmalloc) ' /proc/modules 2>/dev/null || true
        tsp_pz_muos_restore || true
        return 1
    fi

    _pz_stock=$(tsp_pz_module_path zsmalloc 2>/dev/null || true)
    if [ -z "$_pz_stock" ]; then
        # modinfo can fail after unload on some images; fall back to known muOS path.
        _pz_stock="/lib/modules/$(uname -r)/kernel/mm/zsmalloc.ko"
    fi
    [ -f "$_pz_stock" ] || {
        echo "PORTABLE ZRAM: stock muOS zsmalloc module not found"
        tsp_pz_muos_restore || true
        return 1
    }
    _pz_stock_sha=$(tsp_pz_sha256 "$_pz_stock")
    if [ "$_pz_stock_sha" != "$TSP_PZ_KNOWN_STOCK_ZSM_SHA" ]; then
        echo "PORTABLE ZRAM: refusing patched allocator on unknown muOS zsmalloc"
        echo "PORTABLE ZRAM: stock_sha=$_pz_stock_sha"
        tsp_pz_muos_restore || true
        return 1
    fi

    if ! tsp_pz_load_patch; then
        echo "PORTABLE ZRAM: patched allocator load failed"
        tsp_pz_muos_restore || true
        return 1
    fi

    printf '%s\n' "$TSP_PZ_SIZE_MB" > "$TSP_PZ_MUOS_ZRAM_CFG" || { tsp_pz_muos_restore || true; return 1; }
    printf '0\n' > "$TSP_PZ_MUOS_SWAP_CFG" || { tsp_pz_muos_restore || true; return 1; }

    if ! tsp_pz_muos_apply; then
        echo "PORTABLE ZRAM: muOS native zram activation failed"
        tsp_pz_muos_restore || true
        return 1
    fi

    _pz_dev=$(tsp_pz_zram_dev)
    [ -n "$_pz_dev" ] || {
        echo "PORTABLE ZRAM: muOS swap.sh returned but no zram swap is active"
        tsp_pz_muos_restore || true
        return 1
    }

    TSP_PZ_ACTIVE=1
    TSP_PZ_MODE="muos-patched-native"
    echo "PORTABLE ZRAM: muOS patched allocator + native swap.sh active ($_pz_dev, ${TSP_PZ_SIZE_MB} MiB)"
    zramctl "$_pz_dev" 2>/dev/null || true
    return 0
}

# ------------------------------ Knulli path ------------------------------

tsp_pz_knulli_find_service() {
    TSP_PZ_KNULLI_SERVICE=""
    for _pz_s in \
        /usr/share/batocera/services/zramswap \
        /usr/share/batocera/scripts/zramswap
    do
        [ -x "$_pz_s" ] || continue
        TSP_PZ_KNULLI_SERVICE="$_pz_s"
        return 0
    done
    return 1
}

tsp_pz_knulli_restore() {
    [ -r "$TSP_PZ_STATE" ] || return 0
    _pz_was=$(tsp_pz_state_get knulli_was_active 2>/dev/null || echo 0)
    _pz_patch=$(tsp_pz_state_get knulli_patch 2>/dev/null || echo 0)

    tsp_pz_knulli_find_service || return 1
    "$TSP_PZ_KNULLI_SERVICE" stop >/dev/null 2>&1 || true
    sleep 1

    if [ "$_pz_patch" = 1 ]; then
        if ! grep -q '^/dev/zram[0-9][0-9]* ' /proc/swaps 2>/dev/null; then
            tsp_pz_unload_patch
        fi
    fi

    if [ "$_pz_was" = 1 ]; then
        "$TSP_PZ_KNULLI_SERVICE" start >/dev/null 2>&1 || true
    fi

    tsp_pz_state_clear
    echo "PORTABLE ZRAM: Knulli prior zramswap state restored (was_active=$_pz_was)"
    return 0
}

tsp_pz_knulli_start() {
    tsp_pz_knulli_find_service || {
        echo "PORTABLE ZRAM: Knulli zramswap service not found; refusing file/loop swap fallback"
        return 1
    }

    _pz_olddev=$(tsp_pz_zram_dev)
    if [ -n "$_pz_olddev" ]; then TSP_PZ_KNULLI_WAS_ACTIVE=1; else TSP_PZ_KNULLI_WAS_ACTIVE=0; fi

    # Stop an existing service instance so that, when safe, we can substitute the
    # patched allocator underneath it for the game session.
    if [ "$TSP_PZ_KNULLI_WAS_ACTIVE" = 1 ]; then
        "$TSP_PZ_KNULLI_SERVICE" stop >/dev/null 2>&1 || true
        sleep 1
    fi

    _pz_use_patch=0
    _pz_stock=$(tsp_pz_module_path zsmalloc 2>/dev/null || true)
    if [ -n "$_pz_stock" ] && [ -f "$_pz_stock" ]; then
        _pz_stock_sha=$(tsp_pz_sha256 "$_pz_stock")
        if [ "$_pz_stock_sha" = "$TSP_PZ_KNOWN_STOCK_ZSM_SHA" ]; then
            if ! grep -q '^/dev/zram[0-9][0-9]* ' /proc/swaps 2>/dev/null && tsp_pz_unload_module_stack; then
                if tsp_pz_load_patch; then
                    _pz_use_patch=1
                    echo "PORTABLE ZRAM: Knulli uses exact known zsmalloc; no-migration patch enabled"
                fi
            fi
        else
            echo "PORTABLE ZRAM: Knulli zsmalloc hash differs; using Knulli native allocator"
            echo "PORTABLE ZRAM: Knulli stock_sha=$_pz_stock_sha"
        fi
    else
        if [ -d /sys/module/zsmalloc ]; then
            echo "PORTABLE ZRAM: Knulli zsmalloc appears built-in; using Knulli native allocator"
        else
            echo "PORTABLE ZRAM: Knulli zsmalloc module not present before service start"
        fi
    fi

    {
        echo "version=$TSP_PZ_VERSION"
        echo "os=Knulli"
        echo "knulli_was_active=$TSP_PZ_KNULLI_WAS_ACTIVE"
        echo "knulli_patch=$_pz_use_patch"
    } > "$TSP_PZ_STATE" || return 1
    sync

    if ! "$TSP_PZ_KNULLI_SERVICE" start; then
        echo "PORTABLE ZRAM: Knulli native zramswap start failed"
        tsp_pz_knulli_restore || true
        return 1
    fi
    sleep 1

    _pz_dev=$(tsp_pz_zram_dev)
    [ -n "$_pz_dev" ] || {
        echo "PORTABLE ZRAM: Knulli zramswap service returned but no zram swap is active"
        echo "PORTABLE ZRAM: refusing to fall back to file/loop swap"
        tsp_pz_knulli_restore || true
        return 1
    }

    TSP_PZ_ACTIVE=1
    if [ "$_pz_use_patch" = 1 ]; then TSP_PZ_MODE="knulli-patched-native"; else TSP_PZ_MODE="knulli-native"; fi
    echo "PORTABLE ZRAM: Knulli native zramswap active ($_pz_dev mode=$TSP_PZ_MODE)"
    zramctl "$_pz_dev" 2>/dev/null || true
    return 0
}

# ------------------------------ public API -------------------------------

tsp_portable_zram_start() {
    [ "$TSP_PZ_ACTIVE" = 1 ] && return 0
    tsp_pz_detect_os || return 1
    echo "PORTABLE ZRAM: backend=$TSP_PZ_VERSION os=$TSP_PZ_OS"
    case "$TSP_PZ_OS" in
        muOS)   tsp_pz_muos_start ;;
        Knulli) tsp_pz_knulli_start ;;
        *)      return 1 ;;
    esac
}

tsp_portable_zram_stop() {
    tsp_pz_detect_os || return 0
    case "$TSP_PZ_OS" in
        muOS)   tsp_pz_muos_restore || true ;;
        Knulli) tsp_pz_knulli_restore || true ;;
    esac
    TSP_PZ_ACTIVE=0
    TSP_PZ_MODE=""
    return 0
}

# Override the main launcher's memory entry point. muOS/Knulli NEVER fall back
# to the old file/loop swap path if compressed-RAM setup fails.
tsp_memory_setup() {
    if tsp_pz_detect_os; then
        if ! tsp_portable_zram_start; then
            echo "PORTABLE ZRAM: setup failed on $TSP_PZ_OS; continuing WITHOUT launcher swap"
        fi
        return 0
    fi

    # Stock/CrossMix and other existing targets keep their old behavior.
    if type tsp_setup_swap >/dev/null 2>&1; then
        tsp_setup_swap
    fi
}

# Override the launcher's existing cleanup hook.
tsp_zram_release() {
    tsp_portable_zram_stop
}

# ------------------------- embedded muOS module --------------------------

tsp_pz_emit_patch_b64() {
cat <<'TSP_PZ_PATCH_B64'
f0VMRgIBAQAAAAAAAAAAAAEAtwABAAAAAAAAAAAAAAAAAAAAAAAAAHgiBgAAAAAAAAAAAEAAAAAA
AEAALwAuAARMIoslYACRgyxA+WMEAJGDLAD5BAGA0oRQIosGAASLA2hk+N8AA+uAAQBUZ2AA8UAB
AFToBEC5JwRAuR8BB2vNAABUYABA+QUEAPkgjAGpZQAA+cADX9YCUCKLQgRA+UUEAPkimAGpBWgk
+Pr//xeDAQBYBPxc0wBsAVNjAED5gzCDy+T339Lk///ygxgDiyMAAPlAAAC5wANf1h8gA9UAAAAA
AAAAAAAQQPnAA1/WABRA+SAAAPnAA1/WAQBA+WEAQDcACED5wANf1gAAgNL+//8XAwGA0mNQIosE
AAOLA2hj+J8AA+tBAABUAAAh1CMAQPl/CBVyQAAAVAAAIdQlkEGppAQA+QDMIosjYACRhQAA+SMM
APkjEAD5ASxA+SEEANEBLAD5wANf1sECADZCAIBSIwCAUgEBgNIkUCOLBQAEiwZoZPi/AAbrYAAA
VMZgAPHhAQBUIVAiiwMAAYsGaGH4fwAG62ACAFTGYADxQAIAVMEAQPk/CBVy4AAAVAAAIdQiAIBS
